const allInput = $input.all();
const vapiData = allInput.find(r => r.json.toolCallList);
const vapiItems = vapiData.json.toolCallList[0].function.arg_ment.items;
const deliveryType = vapiData.json.toolCallList[0].function.arg_ment.delivery_type;
const deliveryAddress = vapiData.json.toolCallList[0].function.arg_ment.delivery_address || null;
const deliveryZones = allInput.filter(r => r.json.fields && r.json.fields["Delivery zones"]).map(r => r.json.fields);
const menuRecords = allInput.filter(r => r.json.fields && r.json.fields.Item && r.json.fields.Item !== "Item").map(r => r.json.fields);

const normalize = (str) => str.toLowerCase().replace(/\b(and|with|the|in|of|a|an)\b/g, "").replace(/[^a-z0-9 ]/g, "").replace(/\s+/g, " ").trim();

const getMatchScore = (str1, str2) => {
  const words1 = normalize(str1).split(" ").filter(w => w.length > 2);
  const words2 = normalize(str2).split(" ").filter(w => w.length > 2);
  return words1.filter(word => words2.some(w => w === word)).length;
};

const availableItems = [];
const notFound = [];

vapiItems.forEach(vapiItem => {
  const { name, size, quantity } = vapiItem;
  const scored = menuRecords.map(record => ({ record, score: getMatchScore(name, record.Item) }));
  const bestMatch = scored.sort((a, b) => b.score - a.score)[0];
  if (bestMatch && bestMatch.score > 0) {
    const unit_price = Number(bestMatch.record["Unit price"]);
    availableItems.push({
      ordered_name: name,
      matched_name: bestMatch.record.Item,
      availability: bestMatch.record.Availability,
      size,
      quantity,
      unit_price,
      item_total: quantity * unit_price
    });
  } else {
    notFound.push(name);
  }
});

const confirmedItems = availableItems.filter(i => i.availability.toLowerCase() === "available");
const unavailableItems = availableItems.filter(i => i.availability.toLowerCase() !== "available");
const foodTotal = confirmedItems.reduce((sum, i) => sum + i.item_total, 0);
const vapiTotal = vapiItems.reduce((sum, i) => sum + i.item_total, 0);
const totalsMatch = foodTotal === vapiItems.reduce((sum, i) => sum + (i.unit_price * i.quantity), 0);

let deliveryFee = 0;
let matchedZone = null;
let deliveryFeeFound = false;

if (deliveryType === "delivery" && deliveryAddress) {
  const addressNormalized = deliveryAddress.toLowerCase();
  const zoneMatch = deliveryZones.find(zone => {
    const zones = zone["Delivery zones"].toLowerCase().split(",").map(z => z.trim());
    return zones.some(z => addressNormalized.includes(z) || z.includes(addressNormalized));
  });
  if (zoneMatch) {
    deliveryFee = Number(zoneMatch["Delivery fee"]);
    matchedZone = zoneMatch["Delivery zones"];
    deliveryFeeFound = true;
  }
}

const grandTotal = foodTotal + deliveryFee;

let itemsString = "No items confirmed";
if (confirmedItems.length === 1) {
  itemsString = confirmedItems[0].quantity + " " + confirmedItems[0].size + " portion of " + confirmedItems[0].ordered_name;
} else if (confirmedItems.length > 1) {
  const allButLast = confirmedItems.slice(0, -1).map(i => i.quantity + " " + i.size + " portion of " + i.ordered_name).join(", ");
  const last = confirmedItems[confirmedItems.length - 1];
  itemsString = allButLast + " and " + last.quantity + " " + last.size + " portion of " + last.ordered_name;
}

const orderBreakdown = confirmedItems.map(i => i.ordered_name + " x" + i.quantity + " @ N" + i.unit_price + " = N" + i.item_total);
orderBreakdown.push(deliveryType === "delivery" ? "Delivery fee (" + (matchedZone || "zone not found") + "): N" + deliveryFee : "Pickup - no delivery fee");
orderBreakdown.push("Grand Total: N" + grandTotal);

const messageparts = [];
if (unavailableItems.length > 0) messageparts.push("Currently unavailable: " + unavailableItems.map(i => i.ordered_name).join(", "));
if (notFound.length > 0) messageparts.push("Not found on menu: " + notFound.map(i => i).join(", "));
if (deliveryType === "delivery" && !deliveryFeeFound) messageparts.push("Warning: delivery address not found in any zone. Please confirm the address.");
const message = messageparts.length > 0 ? messageparts.join(". ") : "All items are available.";

const discrepancy = !totalsMatch
  ? { detected: true, vapi_sent: vapiTotal, recalculated: foodTotal, difference: foodTotal - vapiTotal, message: "Warning: Vapi total (N" + vapiTotal + ") differs from recalculated total (N" + foodTotal + "). Difference of N" + (foodTotal - vapiTotal) + "." }
  : { detected: false };

return [{
  json: {
    customer_name: vapiData.json["customer's name"],
    phone: vapiData.json["customer's phone number"],
    delivery_type: deliveryType,
    delivery_address: deliveryAddress,
    matched_zone: matchedZone,
    delivery_fee: deliveryFee,
    zone_found: deliveryFeeFound,
    all_items_available: unavailableItems.length === 0 && notFound.length === 0,
    confirmedItems,
    unavailableItems,
    notFound,
    food_total: foodTotal,
    grand_total: grandTotal,
    vapi_total: vapiTotal,
    totals_verified: totalsMatch,
    discrepancy,
    items_string: itemsString,
    order_breakdown: orderBreakdown,
    message
  }
}];

const allInput = $input.all();

const vapiData = allInput.find(r => r.json.toolCallList);
const vapiItems = vapiData.json.toolCallList[0].function.arg_ment.items;

const menuRecords = allInput
  .filter(r => r.json.fields)
  .map(r => r.json.fields);

const normalize = (str) => {
  return str
    .toLowerCase()
    .replace(/\b(and|with|the|in|of|a|an)\b/g, "")
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();
};

const getMatchScore = (str1, str2) => {
  const words1 = normalize(str1).split(" ");
  const words2 = normalize(str2).split(" ");
  return words1.filter(word => words2.includes(word)).length;
};

const availableItems = [];
const notFound = [];

vapiItems.forEach(vapiItem => {
  const { name, size, quantity, unit_price, item_total } = vapiItem;

  const scored = menuRecords.map(record => ({
    record,
    score: getMatchScore(name, record.Item)
  }));

  const bestMatch = scored.sort((a, b) => b.score - a.score)[0];

  if (bestMatch && bestMatch.score > 0) {
    availableItems.push({
      ordered_name: name,
      matched_name: bestMatch.record.Item,
      availability: bestMatch.record.Availability,
      size,
      quantity,
      unit_price,
      item_total: quantity * unit_price
    });
  } else {
    notFound.push(name);
  }
});

const confirmedItems = availableItems.filter(i => i.availability.toLowerCase() === "available");
const unavailableItems = availableItems.filter(i => i.availability.toLowerCase() !== "available");

const totalFromItemTotals = confirmedItems.reduce((sum, i) => sum + i.item_total, 0);
const totalFromUnitPrices = confirmedItems.reduce((sum, i) => sum + (i.unit_price * i.quantity), 0);
const vapiTotal = vapiItems.reduce((sum, i) => sum + i.item_total, 0);
const totalsMatch = totalFromItemTotals === totalFromUnitPrices && totalFromItemTotals === vapiTotal;

const itemsString = confirmedItems.length === 1
  ? `${confirmedItems[0].quantity} ${confirmedItems[0].size} portion of ${confirmedItems[0].ordered_name}`
  : confirmedItems.slice(0, -1).map(i => `${i.quantity} ${i.size} portion of ${i.ordered_name}`).join(", ")
    + " and " + `${confirmedItems[confirmedItems.length - 1].quantity} ${confirmedItems[confirmedItems.length - 1].size} portion of ${confirmedItems[confirmedItems.length - 1].ordered_name}`;

return [{
  json: {
    customer_name: vapiData.json["customer's name"],
    phone: vapiData.json["customer's phone number"],
    delivery_type: vapiData.json.toolCallList[0].function.arg_ment.delivery_type,
    confirmedItems,
    unavailableItems,
    notFound,
    totalCost: totalFromItemTotals,
    vapi_total: vapiTotal,
    totals_verified: totalsMatch,
    discrepancy: !totalsMatch ? {
      detected: true,
      vapi_sent: vapiTotal,
      recalculated: totalFromItemTotals,
      difference: totalFromItemTotals - vapiTotal,
      message: `Warning: Vapi total (₦${vapiTotal}) differs from recalculated total (₦${totalFromItemTotals}). Difference of ₦${totalFromItemTotals - vapiTotal}.`
    } : { detected: false },
    items_string: itemsString,
    order_breakdown: confirmedItems.map(i => `${i.ordered_name} x${i.quantity} @ ₦${i.unit_price} = ₦${i.item_total}`),
    allAvailable: unavailableItems.length === 0 && notFound.length === 0,
    message: [
      unavailableItems.length > 0 ? `Currently unavailable: ${unavailableItems.map(i => i.ordered_name).join(", ")}` : null,
      notFound.length > 0 ? `Not found on menu: ${notFound.map(i => i).join(", ")}` : null
    ].filter(Boolean).join(". ") || "All items are available."
  }
}];

const input = $input.first().json;

// Extract fields safely
const customerName = input["customer's name"] || "Unknown Customer";
const phone = input["customer's phone number"] || "Not provided";
const eventType = input["event type"] || "Not specified";
const eventSummary = input["Event summary"] || "No summary provided";
const date = input["Date"] || "Unknown date";
const time = (input["time"] || "").trim() || "Unknown time";

// Extract from toolCallList safely
const toolCall = input.toolCallList && input.toolCallList[0];
const args = toolCall ? toolCall.function.arg_ment : {};
const priority = args.priority || "medium";
const deliveryType = args.delivery_type || "Not specified";
const items = args.items || [];

// Priority emoji and label
const priorityEmoji = { high: "🔴", medium: "🟡", low: "🟢" };
const priorityLabel = { high: "High", medium: "Medium", low: "Low" };
const emoji = priorityEmoji[priority] || "🟡";

// Build items summary if available
const itemsSummary = items.length > 0
  ? items.map(i => i.quantity + "x " + i.name + " (" + i.size + ") @ N" + i.unit_price).join(", ")
  : "No items captured";

// Build HTML notification message
const notificationMessage = [
  "🚨 <b>New Escalation Alert</b>",
  "━━━━━━━━━━━━━━",
  "",
  "👤 <b>Customer Details</b>",
  "• <b>Name:</b> " + customerName,
  "• <b>Phone:</b> " + phone,
  "",
  "📅 <b>Date and Time</b>",
  "• " + date + " at " + time,
  "",
  "🚦 <b>Priority:</b> " + emoji + " " + priorityLabel[priority],
  "",
  "⚠️ <b>Issue</b>",
  eventSummary,
  "",
  "🛒 <b>Order Details</b>",
  "• <b>Delivery Type:</b> " + deliveryType,
  "• <b>Items:</b> " + itemsSummary,
  "",
  "━━━━━━━━━━━━━━",
  "📞 Please call <b>" + customerName + "</b> on <b>" + phone + "</b> as soon as possible to resolve this."
].join("\n");

return [{
  json: {
    customer_name: customerName,
    phone,
    date,
    time,
    priority,
    priority_emoji: emoji,
    escalation_reason: eventType,
    escalation_summary: eventSummary,
    delivery_type: deliveryType,
    items_captured: itemsSummary,
    notification_message: notificationMessage,
    has_order_context: items.length > 0,
    requires_callback: true
  }
}];
